  {kind="narration",pos=159.954,dur=10.36,name="NARRATION 006 | If you tuned into those broadcasts as a stranger, you woul",text="If you tuned into those broadcasts as a stranger, you would think Angela was confronting an enemy she had been tracking from a distance.",path="",status="NARRATION RECORDING REQUIRED",line=66},
