  {kind="narration",pos=3199.991,dur=6.711,name="NARRATION 144 | And as the broadcast continued, Angela warned the people l",text="And as the broadcast continued, Angela warned the people listening that they were under investigation.",path="",status="NARRATION RECORDING REQUIRED",line=608},
  {kind="archive_angela",pos=3207.002,dur=31.1,name="ARCHIVE C42 AQ-0264 | 045a__AQ-0264__Quit_Running_Mouth.wav",text="Manuscript line 609\n[CLIP #037-M | AQ-0264 & AQ-0266 | *Petty Space* (20260908_1wxWjlrwXokJQ), Sept 8, 2026, 1250.0s & 1345.0s]\nManifest status: existing\nAudio cut boundaries/context and speaker NOT independently verified. Audition before publication.\nOriginal source: C:\\Users\\Logan\\OneDrive\\Documents\\AngelaMaster\\media\\AQ-0264_Angela_Maggard.wav",path="C:\\Users\\Logan\\copy-spaces-to-youtube-pipeline\\papertrail_archival_audio_ordered\\045a__AQ-0264__Quit_Running_Mouth.wav",status="existing",line=609},
