  {kind="sfx",pos=3780.78,dur=0.12,name="SFX 14 | SFX: Subtle phone tactile send click",text="SFX: Subtle phone tactile send click",path="C:\\Users\\Logan\\copy-spaces-to-youtube-pipeline\\THE_PAPER_TRAIL_REAPER_ASSEMBLY_20261112\\SCRATCH_phone_send_click.wav",status="SCRATCH - replace before release",line=714},
  {kind="reading",pos=3780.78,dur=6.009,name="WRITTEN READING 004 | \"Thats old news apparently hes shared nudes a bunch with h",text="\"Thats old news apparently hes shared nudes a bunch with his close friends.\"",path="",status="RECORDING REQUIRED",line=718},
