  {kind="narration",pos=3787.09,dur=8.413,name="NARRATION 172 | The next day, Angela forwarded Sav a screenshot of another",text="The next day, Angela forwarded Sav a screenshot of another person's claims about me. That person was Kimball.",path="",status="NARRATION RECORDING REQUIRED",line=722},
