  {kind="reading",pos=3811.161,dur=14.699,name="WRITTEN READING 005 | \"He sent me a nude video of a girl in the community (I don",text="\"He sent me a nude video of a girl in the community (I don't believe I have evidence for that) and he produced a nude AI image of a woman in the community.\"",path="",status="RECORDING REQUIRED",line=729},
