  {kind="narration",pos=4171.206,dur=7.927,name="NARRATION 195 | In another recorded confrontation, Angela defended her dec",text="In another recorded confrontation, Angela defended her decision to request the police welfare check at Sav's home.",path="",status="NARRATION RECORDING REQUIRED",line=816},
  {kind="narration",pos=4179.433,dur=10.034,name="NARRATION 196 | Her explanation matters. She said she feared for Sav's saf",text="Her explanation matters. She said she feared for Sav's safety, understood that the call might end their friendship, and made it anyway.",path="",status="NARRATION RECORDING REQUIRED",line=818},
  {kind="narration",pos=4189.767,dur=4.359,name="NARRATION 197 | \"Angela, shut the fuck up, Angela. Angela, shut up.\"",text="\"Angela, shut the fuck up, Angela. Angela, shut up.\"",path="",status="NARRATION RECORDING REQUIRED",line=822},
